px,6.2vw,82px);letter-spacing:-.07em;line-height:.91;margin:23px 0 21px;font-weight:700}.outline-text{-webkit-text-stroke:1px #e9f4f2;color:transparent}.pink-text{color:var(--pink)}.hero-copy>p,.section-heading>p{font-size:15px;color:#a3b2bb;line-height:1.6;max-width:430px;margin:0}.hero-actions{display:flex;align-items:center;gap:25px;margin-top:29px}.primary-btn,.secondary-btn,.text-btn,.mode-arrow,.back-btn,.skip-btn,.finish-btn{font-family:var(--mono);font-size:10px;letter-spacing:.04em;cursor:pointer;transition:.18s ease}.primary-btn{border:0;background:var(--lime);color:#0a171e;padding:16px 21px;font-weight:500;box-shadow:4px 4px 0 #73933f}.primary-btn span{font-size:16px;margin-left:20px}.primary-btn:hover{transform:translate(2px,2px);box-shadow:2px 2px 0 #73933f;background:#d9ff93}.text-btn{border:0;color:#a6b6bf;background:none;padding:12px 0}.text-btn span{color:var(--cyan);margin-left:7px}.hero-stats{display:flex;align-items:center;gap:23px;margin-top:45px}.hero-stats div{display:grid;gap:6px}.hero-stats b{font:20px var(--mono);color:#f3f5ef}.hero-stats small{font:8px var(--mono);letter-spacing:.12em;color:#80919c}.hero-stats i{height:32px;width:1px;background:var(--line)}.hero-visual{margin-top:42px;border:1px solid #335064;background:#0a1a27;position:relative;box-shadow:0 18px 50px #0005}.stadium-label,.visual-caption{height:31px;display:flex;justify-content:space-between;align-items:center;padding:0 12px;color:#92a7ae;font:8px var(--mono);letter-spacing:.12em}.hero-visual canvas{display:block;width:100%;height:auto;aspect-ratio:960/590;image-rendering:pixelated}.visual-caption{border-top:1px solid #243b49;color:var(--cyan)}.visual-caption span:first-child{color:#f0f3ed}.mode-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-top:20px}.mode-card{min-height:188px;border:1px solid var(--line);background:linear-gradient(120deg,#102232,#0d1b28);position:relative;padding:22px 23px 17px;display:grid;grid-template-columns:45px 1fr 38px;grid-template-rows:1fr auto;column-gap:15px}.mode-card:before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--pink)}.endless-card:before{background:var(--cyan)}.mode-icon{font:24px var(--mono);color:var(--pink);padding-top:2px}.endless-card .mode-icon{color:var(--cyan);font-size:30px}.mode-card .eyebrow{font-size:8px}.mode-card h2{font-size:20px;letter-spacing:.01em;margin:8px 0 5px}.mode-card p{color:#9baeb8;font-size:12px;margin:0}.mode-arrow{background:transparent;border:1px solid var(--line);color:#dbe4e2;font-size:17px;width:36px;height:36px;grid-column:3;grid-row:1;align-self:start}.mode-foot{grid-column:1/4;display:flex;gap:9px;border-top:1px solid #ffffff12;padding-top:13px;color:#8195a1;font:8px var(--mono);letter-spacing:.08em}.mode-foot span:last-child{color:#c4d2d3}.home-footer{display:flex;justify-content:space-between;color:#617684;font:8px var(--mono);letter-spacing:.12em;padding:27px 0 0}.back-btn{background:none;border:0;color:#9eb0bb;padding:0;font-size:9px}.back-btn:hover{color:var(--cyan)}.section-heading{margin:42px 0 29px}.section-heading h1{font-size:clamp(44px,6vw,72px);margin:18px 0}.section-heading>p{max-width:540px}.character-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.character-card{border:1px solid var(--line);background:#0d1d2b;padding:18px 15px;cursor:pointer;position:relative;min-height:148px;text-align:left;color:var(--text);font:inherit;transition:.2s}.character-card:hover{border-color:#5a7a89;transform:translateY(-2px)}.character-card.selected{border-color:var(--pink);box-shadow:inset 0 0 0 1px var(--pink);background:linear-gradient(145deg,#241a2c,#0f1d2b)}.character-card.selected:after{content:'✓';position:absolute;right:12px;top:12px;color:var(--lime);font:13px var(--mono)}.player-sprite{width:42px;height:50px;display:grid;place-items:center;font-size:26px;margin-bottom:12px;image-rendering:pixelated;filter:drop-shadow(3px 4px 0 #0008)}.character-card b{display:block;font-size:14px}.character-card small{display:block;color:#8599a5;font:9px var(--mono);margin-top:6px}.selection-bottom{border-top:1px solid var(--line);margin-top:28px;padding-top:20px;display:flex;align-items:center;justify-content:space-between}.selected-player{display:flex;align-items:center;gap:12px}.mini-player{width:41px;height:41px;display:grid;place-items:center;background:#152838;font-size:21px}.selected-player div{display:grid;gap:4px}.selected-player small,.score-label small{font:8px var(--mono);color:#8499a5;letter-spacing:.1em}.selected-player b{font-size:14px}.game-topline{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.game-mode-label{font:9px var(--mono);letter-spacing:.1em;color:#c5d2d5}.game-mode-label span{color:var(--pink);padding:0 5px}.score-label{text-align:right;display:grid;gap:3px}.score-label b{font:19px var(--mono);color:var(--lime)}.game-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(325px,.8fr);gap:18px;align-items:start}.stadium-frame{position:relative;border:1px solid #2f4d5e;background:#071a25;overflow:hidden}.stadium-frame canvas{display:block;width:100%;height:auto;aspect-ratio:16/9;image-rendering:pixelated}.canvas-hud{position:absolute;inset:10px 12px auto;display:flex;justify-content:space-between;pointer-events:none;color:#b9d1cf;font:8px var(--mono);letter-spacing:.12em;text-shadow:1px 2px #07111d}.hud-live{color:var(--pink)}.hud-live i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--pink);margin-right:5px;box-shadow:0 0 8px var(--pink)}.scene-banner{position:absolute;inset:0;display:grid;place-items:center;font:clamp(13px,3vw,30px) var(--pixel);color:#fff;text-align:center;text-shadow:3px 3px #f34d97,6px 6px #08111a;opacity:0;pointer-events:none}.scene-banner.show{animation:banner-pop 1.8s ease both}@keyframes banner-pop{0%{opacity:0;transform:scale(.7)}15%,70%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(1.05)}}.pitch-meta{display:flex;justify-content:space-between;padding:10px 2px;color:#8298a4;font:8px var(--mono);letter-spacing:.08em}.pitch-meta span:nth-child(2){color:var(--cyan)}.pitch-meta b{color:var(--lime)}.feedback-line{height:25px;font:10px var(--mono);color:var(--lime);padding:5px 2px}.feedback-line.error{color:#ff879b}.quiz-panel{border:1px solid var(--line);background:linear-gradient(145deg,#102131,#0b1824);padding:18px 20px 16px}.question-meta{display:flex;justify-content:space-between;color:#95aab3;font:8px var(--mono);letter-spacing:.08em}.question-meta span:last-child{color:var(--cyan)}.timer-row{display:flex;align-items:center;gap:12px;margin:18px 0 21px}.timer-track{height:5px;flex:1;background:#273a45}.timer-track div{height:100%;width:100%;background:var(--lime);transition:width .25s linear,background .2s}.timer-number{display:flex;align-items:baseline;gap:4px}.timer-number b{font:22px var(--mono);color:var(--lime)}.timer-number small{font:8px var(--mono);color:#91a4ad}.type-chip{font:8px var(--mono);padding:5px 7px;border:1px solid #395260;color:var(--cyan);display:inline-block;letter-spacing:.08em}.question-copy h2{font-size:clamp(20px,2vw,26px);line-height:1.2;letter-spacing:-.03em;margin:12px 0 9px}.question-copy p{font-size:11px;color:#91a5ae;line-height:1.5;margin:0 0 20px}.input-label{display:block;font:8px var(--mono);letter-spacing:.12em;color:#a8b8bd;margin-bottom:8px}.answer-input-wrap{display:flex;border:1px solid #486174;background:#08151f;transition:border-color .2s}.answer-input-wrap:focus-within{border-color:var(--cyan)}.answer-input-wrap input{min-width:0;flex:1;background:transparent;border:0;outline:0;color:white;font:14px var(--sans);padding:12px}.answer-input-wrap input::placeholder{color:#59707d}.submit-btn{border:0;background:var(--cyan);color:#06151a;width:45px;font-size:19px;cursor:pointer}.submit-btn:hover{background:#a2fff5}.input-help{color:#69818d;font:8px var(--mono);margin-top:7px}.question-actions{display:flex;justify-content:space-between;align-items:center;margin-top:12px;min-height:34px}.skip-btn,.finish-btn{border:1px solid #354c5a;color:#a1b1b8;background:transparent;padding:9px 10px;font-size:8px}.skip-btn:hover{border-color:var(--pink);color:var(--pink)}.skip-btn span{color:var(--pink);margin-left:7px}.finish-btn{background:var(--lime);border-color:var(--lime);color:#0a171e}.found-answers{margin-top:9px;display:flex;gap:5px;flex-wrap:wrap;max-height:58px;overflow:auto}.found-answers span{font:8px var(--mono);padding:5px 6px;background:#193629;border:1px solid #355942;color:#c9f39d}.hidden{display:none!important}.round-progress{margin-top:15px;padding-top:12px;border-top:1px solid #ffffff12;display:flex;justify-content:space-between;align-items:center;color:#8196a1;font:8px var(--mono);letter-spacing:.07em}.round-progress #progress-dots{display:flex;gap:5px}.round-progress #progress-dots i{width:7px;height:7px;background:#334653}.round-progress #progress-dots i.done{background:var(--lime)}.round-progress #progress-dots i.current{background:var(--pink);box-shadow:0 0 7px #ff4d9d}.results-kicker{display:flex;justify-content:space-between;color:var(--cyan);font:9px var(--mono);letter-spacing:.14em}.results-heading{text-align:center;margin:37px 0 21px}.results-heading .eyebrow{justify-content:center}.results-heading h1{font-size:clamp(40px,6vw,68px);margin:16px 0}.results-heading p{color:#93a6af;font-size:13px}.result-score-card{margin:auto;max-width:440px;text-align:center;border:1px solid #395467;background:linear-gradient(145deg,#122738,#0b1824);padding:21px;position:relative;box-shadow:7px 7px 0 #09151e}.result-score-card small{display:block;font:8px var(--mono);letter-spacing:.15em;color:#92a7b0}.result-score-card strong{display:block;font:clamp(45px,7vw,72px) var(--mono);color:var(--lime);line-height:1.2}.result-score-card>span{font:9px var(--mono);color:#a7bac1;letter-spacing:.1em}.result-rank{color:var(--pink);font:8px var(--mono);letter-spacing:.1em;margin-top:13px}.result-grid{max-width:680px;margin:24px auto;display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line)}.result-grid>div{padding:15px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);display:grid;gap:7px}.result-grid>div:nth-child(3n){border-right:0}.result-grid>div:nth-child(n+4){border-bottom:0}.result-grid small{font:7px var(--mono);color:#8297a2;letter-spacing:.1em}.result-grid b{font-size:14px}.results-actions{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}.secondary-btn{padding:15px 19px;background:transparent;color:#d4e0df;border:1px solid #435965}.secondary-btn:hover{border-color:var(--cyan);color:var(--cyan)}.result-note{text-align:center;color:#80949e;font:9px var(--mono);margin-top:17px}.settings-card{max-width:600px;background:#102130;border:1px solid var(--line);padding:25px}.settings-card label{display:flex;justify-content:space-between;font:9px var(--mono);color:#c0ccd0;letter-spacing:.1em;margin:8px 0 13px}.settings-card label span{color:var(--cyan)}.settings-card input{width:100%;margin-bottom:20px;accent-color:var(--lime)}.settings-card p,.source-note{font-size:11px;color:#8ea2ac;line-height:1.6}.how-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.how-grid article{border:1px solid var(--line);background:#0d1d2b;padding:19px}.how-grid b{font:9px var(--mono);color:var(--cyan);letter-spacing:.08em}.how-grid p{font-size:13px;color:#a4b3b9;line-height:1.6;margin-bottom:0}.source-note{max-width:740px;margin-top:22px}.toast{position:fixed;bottom:22px;left:50%;transform:translate(-50%,20px);background:#d6ff80;color:#0c1a21;padding:12px 18px;font:10px var(--mono);z-index:10;opacity:0;transition:.2s;pointer-events:none;box-shadow:4px 4px 0 #718e3e}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#02080dcc;display:grid;place-items:center;z-index:20;padding:20px}.modal{max-width:430px;width:100%;background:#102130;border:1px solid #3b5868;padding:28px;position:relative}.modal-close{position:absolute;right:12px;top:10px;background:none;border:0;color:#b7c5ca;font-size:24px;cursor:pointer}.modal h2{font-size:24px;margin:15px 0 8px}.modal p{color:#96aab2;font-size:13px;line-height:1.5}.modal-actions{display:flex;gap:10px;margin-top:23px}.modal-actions>*{flex:1}.modal .primary-btn{padding:12px}.modal .primary-btn span{display:none}
@media(min-width:1050px){#home-screen.active{display:grid;grid-template-columns:.94fr 1.06fr;column-gap:42px;align-items:center;padding-top:35px}.hero-copy{padding:0}.hero-visual{margin:0}.mode-grid{grid-column:1/3;margin-top:25px}.home-footer{grid-column:1/3}.hero-copy h1{font-size:clamp(50px,5.4vw,79px)}}
@media(max-width:850px){.app-shell{padding:0 4%}.game-layout{grid-template-columns:1fr}.quiz-panel{max-width:none}.pitch-column{order:0}.quiz-panel{order:1}.game-layout{gap:7px}.character-grid{grid-template-columns:repeat(3,1fr)}.screen{padding-top:37px}.hero-visual{margin-top:30px}}
@media(max-width:580px){.app-shell{padding:0 17px}.topbar{height:72px}.brand{font-size:14px}.brand-mark{width:34px;height:34px;font-size:9px}.streak-pill{padding:8px;font-size:8px;gap:5px}.topbar-right{gap:7px}.icon-btn{width:33px;height:33px}.screen{min-height:calc(100vh - 73px);padding:32px 0}.hero-copy{padding-top:11px}.hero-copy h1{font-size:54px}.hero-copy>p{font-size:13px}.hero-stats{gap:13px;margin-top:31px}.hero-stats b{font-size:16px}.hero-stats small{font-size:7px}.mode-grid{grid-template-columns:1fr}.mode-card{min-height:158px;padding:18px}.home-footer{font-size:7px;gap:10px}.hero-actions{gap:14px}.primary-btn{font-size:9px;padding:14px 14px}.primary-btn span{margin-left:10px}.character-grid{grid-template-columns:repeat(2,1fr);gap:8px}.character-card{min-height:130px;padding:13px}.section-heading{margin:32px 0 23px}.selection-bottom{gap:10px}.selection-bottom .primary-btn{white-space:nowrap}.game-topline{margin-bottom:13px}.game-mode-label{font-size:7px}.game-topline .back-btn{font-size:8px}.score-label b{font-size:16px}.pitch-meta{font-size:6px;gap:4px}.quiz-panel{padding:16px}.question-copy h2{font-size:22px}.question-copy p{font-size:10px}.result-grid>div{padding:11px 8px}.result-grid small{font-size:6px}.result-grid b{font-size:12px}.results-actions{display:grid;grid-template-columns:1fr 1fr}.results-actions .primary-btn{grid-column:1/3}.how-grid{grid-template-columns:1fr}.home-footer span:last-child{text-align:right}.hero-visual .stadium-label,.visual-caption{font-size:6px}.hero-visual .stadium-label{height:26px}.results-heading{margin:29px 0 18px}}

(() => {
'use strict';
const BANK = window.TOPBINS_QUESTIONS || [];
const $ = id => document.getElementById(id);
const screens = ['home-screen','character-screen','game-screen','results-screen','settings-screen','how-screen'];
const players = [
 {name:'Lionel Messi',short:'MESSI · 10',emoji:'🐐',kit:'#33b9eb',accent:'#ffffff',celebration:'SHIRT TO THE CROWD'},
 {name:'Cristiano Ronaldo',short:'RONALDO · 7',emoji:'⭐',kit:'#e3344e',accent:'#f5d735',celebration:'SIIIIII!'},
 {name:'Neymar Jr',short:'NEYMAR · 10',emoji:'🎭',kit:'#f5d331',accent:'#1681d7',celebration:'SAMBA DANCE'},
 {name:'Sergio Agüero',short:'AGÜERO · 10',emoji:'⚡',kit:'#62a9ed',accent:'#a6d8ff',celebration:'AGÜEROOOO!'},
 {name:'Ronaldinho',short:'RONALDINHO · 10',emoji:'😁',kit:'#298cde',accent:'#ffcf39',celebration:'THE NO-LOOK'},
 {name:'Kylian Mbappé',short:'MBAPPÉ · 7',emoji:'🚀',kit:'#173e9d',accent:'#ed334c',celebration:'ARMS CROSSED'},
 {name:'Erling Haaland',short:'HAALAND · 9',emoji:'🦁',kit:'#6cace4',accent:'#ffffff',celebration:'ZEN MODE'},
 {name:'Thierry Henry',short:'HENRY · 14',emoji:'👑',kit:'#e63e4d',accent:'#f6f1e7',celebration:'KNEE SLIDE'},
 {name:'Marta',short:'MARTA · 10',emoji:'💫',kit:'#f3c53d',accent:'#208bdf',celebration:'THE POINT'}
];
const rarityPoints = {Common:10,Uncommon:20,Rare:35,'Extremely Rare':55};
const rarityOrder = {Common:1,Uncommon:2,Rare:3,'Extremely Rare':4};
const goalPoints = {'TAP IN':20,'OFF THE POST':27,'SCREAMER!':55,'BICYCLE KICK':80,'TOP BINS!':100};
const data = loadData();
let selectedPlayer = Math.max(0, Math.min(players.length-1, data.player || 0));
let mode = 'daily', roundQuestions = [], qIndex = 0, currentScore = 0, timer = 30, timerInterval = null, qStartedAt = 0;
let roundStats = null, foundCurrent = new Set(), questionLocked = false, currentGoal = '', animation = null;
let ambientOn = false, audioCtx = null, ambientNodes = [], toastTimer = 0;
let previousScreen = 'home-screen';
const canvasStates = new WeakMap();

function loadData(){try{return Object.assign({games:0,points:0,best:0,correctTotal:0,dailyStreak:0,lastDaily:null,completedDaily:null,player:0,playedIds:[],sfx:70,music:35,muted:false,lastResult:null},JSON.parse(localStorage.getItem('topbins-save')||'{}'));}catch{return {games:0,points:0,best:0,correctTotal:0,dailyStreak:0,lastDaily:null,completedDaily:null,player:0,playedIds:[],sfx:70,music:35,muted:false,lastResult:null};}}
function saveData(){try{localStorage.setItem('topbins-save',JSON.stringify(data));}catch{}}
function showScreen(id){screens.forEach(s=>$(s).classList.toggle('active',s===id));window.scrollTo({top:0,behavior:'smooth'});if(id==='home-screen')startHomeCanvas();}
function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
function todayKey(){return new Date().toISOString().slice(0,10)}
function seededRandom(seed){let n=seed>>>0;return()=>{n=(n*1664525+1013904223)>>>0;return n/4294967296;}}
function hashString(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0;}
function shuffle(items,random=Math.random){const a=items.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;}
function normalize(text){return String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ');}
function answerRows(q){return q.answers.map(row=>{const values=row.slice(0,-1);const rarity=row[row.length-1];return {name:values[0],aliases:values.slice(1),rarity};});}
function matchAnswer(q,input){const normalized=normalize(input);if(!normalized)return null;return answerRows(q).find(row=>[row.name,...row.aliases].some(alias=>normalize(alias)===normalized))||null;}
function rarityGoal(rarity,q,level=1){const r=rarityOrder[rarity]||1;const pressure=Math.min(1,Math.max(0,(q.difficulty+level-3)/8));if(r>=4&&pressure>.58)return 'TOP BINS!';if(r>=4)return 'BICYCLE KICK';if(r>=3&&pressure>.2)return 'BICYCLE KICK';if(r>=3)return 'SCREAMER!';if(r===2)return 'OFF THE POST';return 'TAP IN';}
function scoreFor(rarity,goal,q,level){const base=goalPoints[goal]||10;if(goal==='TAP IN')return base;const top=Math.min(10,Math.floor((q.difficulty+level)/2));return base+top;}
